[CmdletBinding()]
param([string]$BundlesDirectory='ES/Output/WebPageStudio/bundles',[string]$OutputPath='ES/Output/WebPageStudio/webpagestudio-migration-report-v4.json')
$ErrorActionPreference='Stop';$OutputEncoding=[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$base=& (Join-Path $root 'ES/Automation/WebPageStudio/New-ESWebPageStudioMigrationReportV3.ps1') -BundlesDirectory $BundlesDirectory -OutputPath 'ES/Output/WebPageStudio/webpagestudio-migration-report-v3.json'|ConvertFrom-Json;$refresh=@(Get-ChildItem -LiteralPath (Join-Path $root $BundlesDirectory) -Directory -Filter 'locale-bundle-refresh-v*'|Where-Object Name -notlike '*-offline');$offline=@(Get-ChildItem -LiteralPath (Join-Path $root $BundlesDirectory) -Directory -Filter 'locale-bundle-refresh-*-offline');$summary=[pscustomobject]@{refreshedBundleCount=$refresh.Count;refreshedOfflinePackageCount=$offline.Count;refreshedBundleNames=@($refresh|% Name);refreshedOfflineNames=@($offline|% Name)};$base|Add-Member -NotePropertyName refreshedArtifacts -NotePropertyValue $summary -Force;$out=[IO.Path]::GetFullPath((Join-Path $root $OutputPath));if(-not $out.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'OutputPath must remain under project root.'};[IO.File]::WriteAllText($out,($base|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false));[pscustomobject]@{status=$base.status;reportPath=$out.Replace($root,'').Replace('\','/');refreshedBundles=$summary.refreshedBundleCount;refreshedOfflinePackages=$summary.refreshedOfflinePackageCount;offlineAudit=$base.offlinePackages.status}|ConvertTo-Json -Depth 8
